import java.io.OutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.Arrays;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.stream.Stream;
import java.util.regex.Matcher;
import java.util.StringTokenizer;
import java.util.Optional;
import java.util.regex.Pattern;
import java.io.BufferedReader;
import java.io.InputStream;

/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskB solver = new TaskB();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskB {
        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int n = in.nextInt();
            String input = in.next();
            String pattern = "\\([\\w_]*\\)";
            String[] outSite = input.split(pattern);
            int longest = Arrays.stream(outSite).map(s -> longestWords(s)).max(Integer::compare).orElse(0);
            Pattern r = Pattern.compile(pattern);
            Matcher m = r.matcher(input);
            long numberInside = 0;
            while (m.find()) {
                numberInside += Arrays.stream(trimParentheses(m.group()).split("_")).filter(s -> !s.isEmpty()).count();
            }
            out.println(longest + " " + numberInside);
        }

        private int longestWords(String line) {
            return Arrays.stream(line.split("_")).map(String::length).max(Integer::compare).orElse(0);
        }

        private String trimParentheses(String input) {
            String temp = input.substring(1, input.length());
            return temp.substring(0, temp.length() - 1);
        }

    }

    static class InputReader {
        private StringTokenizer tokenizer;
        private BufferedReader reader;

        public InputReader(InputStream inputStream) {
            reader = new BufferedReader(new InputStreamReader(inputStream));
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

    }
}


